<?php get_header(); while(have_posts()):the_post(); $type=get_post_type(); $audio_id=(int) nta_meta('nta_audio_file'); $audio_url=$audio_id ? wp_get_attachment_url($audio_id) : nta_meta('nta_external_url'); ?><section class="page-hero"><div class="wrap"><p class="eyebrow"><?php echo esc_html(get_post_type_object($type)->labels->singular_name); ?></p><h1><?php the_title(); ?></h1><p class="meta"><?php echo esc_html(nta_meta($type==='nta_video'?'nta_video_date':($type==='nta_audio'?'nta_audio_date':'nta_date')) ?: get_the_date()); ?></p></div></section><section class="section"><article class="wrap prose" data-aos="fade-up"><?php if($type==='nta_audio' && $audio_url): ?><audio class="w-full mb-8" controls preload="metadata"><source src="<?php echo esc_url($audio_url); ?>"></audio><?php endif; ?><?php if($type==='nta_video' && nta_meta('nta_external_url')): ?><p><a class="button" href="<?php echo esc_url(nta_meta('nta_external_url')); ?>">Watch video</a></p><?php endif; ?><?php if(nta_meta('nta_speaker')): ?><p class="meta">Speaker: <?php echo esc_html(nta_meta('nta_speaker')); ?></p><?php endif; ?><?php the_content(); ?></article></section><?php endwhile; get_footer();
